import { InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    overageAllowedEnum,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { OfferingType } from './OfferingType.js';
import { Offering } from './offeringPackage.entity.js';

const dimensionTemplate = {
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
    rounding: roundingEnum.round,
    usageIncrement: '1',
    consumptionUnit: {
        unit: countBasedUnits['count-based'],
        type: 'count',
    },
};

const buildLineItems = async ({
    dimensions,
    usage,
    freeDimensionOnInvoice = FreeDimensionOnInvoice.show,
}: {
    dimensions: ReadOfferingResponseData['dimensions'];
    usage: Array<{ dimensionId: string; total: number }>;
    freeDimensionOnInvoice?: FreeDimensionOnInvoice;
}) => {
    const offering = {
        offeringId: 'off-1',
        offeringName: 'Plan',
        offeringType: OfferingType.usageBased,
        currency: SupportedCurrencies.USD,
        billingCycle: ValidBillingCycles.monthly,
        dimensions,
    } as ReadOfferingResponseData;
    const startDate = new Date('2026-07-01T00:00:00Z');
    const endDate = new Date('2026-08-01T00:00:00Z');
    const offeringInstance = Offering.getInstance(
        offering,
        'cus_1',
        'biz_1',
        undefined,
        { freeDimensionOnInvoice } as ReadSettingsResponseData,
        undefined,
        undefined,
        undefined,
        usage.map(({ dimensionId, total }) => ({
            offeringId: offering.offeringId,
            dimensionId,
            usage: [
                {
                    value: `${total}`,
                    startTime: startDate.toISOString(),
                    endTime: endDate.toISOString(),
                },
            ],
        })),
    );
    const lineItems = await Offering.getLineItemsForUsage({
        startDate,
        endDate,
        lineItems: new InvoiceLineItems(),
        businessID: 'biz_1',
        customerId: 'cus_1',
        customerService: undefined,
        dimensions,
        offeringInstance,
    });
    return lineItems.getLineItems();
};

describe('Entitlements, overage and free dimensions on invoice lines', () => {
    test('a dimension without an allowance is charged for all of its usage', async () => {
        const lines = await buildLineItems({
            dimensions: [{ ...dimensionTemplate, dimensionId: 'd1', dimensionName: 'D1', consumptionPrice: '0.01' }],
            usage: [{ dimensionId: 'd1', total: 100 }],
        });
        expect(lines).toEqual([expect.objectContaining({ name: 'D1 - Plan', quantity: 100, unitCost: 0.01 })]);
    });

    test('only the usage beyond an exhausted allowance is charged when overage is permitted', async () => {
        const lines = await buildLineItems({
            dimensions: [
                {
                    ...dimensionTemplate,
                    dimensionId: 'd1',
                    dimensionName: 'D1',
                    consumptionPrice: '10.00',
                    usageEntitlement: 10,
                    overageAllowed: overageAllowedEnum.true,
                },
            ],
            usage: [{ dimensionId: 'd1', total: 12 }],
        });
        expect(lines).toEqual([expect.objectContaining({ name: 'D1 - Plan', quantity: 2, unitCost: 10 })]);
    });

    test('an unexhausted allowance carries no line', async () => {
        const lines = await buildLineItems({
            dimensions: [
                {
                    ...dimensionTemplate,
                    dimensionId: 'd1',
                    dimensionName: 'D1',
                    consumptionPrice: '0.02',
                    usageEntitlement: 100,
                    overageAllowed: overageAllowedEnum.true,
                },
            ],
            usage: [{ dimensionId: 'd1', total: 80 }],
        });
        expect(lines).toEqual([]);
    });

    test('an unlimited allowance carries no line', async () => {
        const lines = await buildLineItems({
            dimensions: [
                {
                    ...dimensionTemplate,
                    dimensionId: 'd1',
                    dimensionName: 'D1',
                    consumptionPrice: '0.20',
                    usageEntitlement: 'inf',
                    overageAllowed: overageAllowedEnum.true,
                },
            ],
            usage: [{ dimensionId: 'd1', total: 40 }],
        });
        expect(lines).toEqual([]);
    });

    test('an exhausted allowance carries no line when the plan forbids overage', async () => {
        const lines = await buildLineItems({
            dimensions: [
                {
                    ...dimensionTemplate,
                    dimensionId: 'd1',
                    dimensionName: 'D1',
                    consumptionPrice: '1.00',
                    usageEntitlement: 5,
                    overageAllowed: overageAllowedEnum.false,
                },
                {
                    ...dimensionTemplate,
                    dimensionId: 'd2',
                    dimensionName: 'D2',
                    consumptionPrice: '0.10',
                    usageEntitlement: 50,
                },
            ],
            usage: [
                { dimensionId: 'd1', total: 7 },
                { dimensionId: 'd2', total: 70 },
            ],
        });
        expect(lines).toEqual([]);
    });

    test('a dimension priced at zero is shown with its usage when free dimensions are shown', async () => {
        const lines = await buildLineItems({
            dimensions: [{ ...dimensionTemplate, dimensionId: 'd1', dimensionName: 'D1', consumptionPrice: '0.00' }],
            usage: [{ dimensionId: 'd1', total: 10 }],
            freeDimensionOnInvoice: FreeDimensionOnInvoice.show,
        });
        expect(lines).toEqual([expect.objectContaining({ name: 'D1 - Plan', quantity: 10, unitCost: 0 })]);
    });

    test('a dimension priced at zero is left off when free dimensions are hidden', async () => {
        const lines = await buildLineItems({
            dimensions: [{ ...dimensionTemplate, dimensionId: 'd1', dimensionName: 'D1', consumptionPrice: '0.00' }],
            usage: [{ dimensionId: 'd1', total: 10 }],
            freeDimensionOnInvoice: FreeDimensionOnInvoice.hide,
        });
        expect(lines).toEqual([]);
    });

    test('a priced dimension without usage carries no line', async () => {
        const lines = await buildLineItems({
            dimensions: [
                { ...dimensionTemplate, dimensionId: 'd1', dimensionName: 'D1', consumptionPrice: '0.50' },
                { ...dimensionTemplate, dimensionId: 'd2', dimensionName: 'D2', consumptionPrice: '0.50' },
            ],
            usage: [{ dimensionId: 'd2', total: 4 }],
        });
        expect(lines).toEqual([expect.objectContaining({ name: 'D2 - Plan', quantity: 4, unitCost: 0.5 })]);
    });
});
EOF
